import{_ as a,C as i,o as n,c as o,j as t,a as r,E as h,ak as l}from"./chunks/framework.sV-XtlWr.js";const b=JSON.parse('{"title":"Notifications & alerts","description":"Browser, email, Slack, Microsoft Teams and webhook channels, the events they fire on, and per-project subscriptions with digests and mute.","frontmatter":{"title":"Notifications & alerts","description":"Browser, email, Slack, Microsoft Teams and webhook channels, the events they fire on, and per-project subscriptions with digests and mute.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/notifications.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/notifications.html"}],["meta",{"property":"og:title","content":"Notifications & alerts | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Browser, email, Slack, Microsoft Teams and webhook channels, the events they fire on, and per-project subscriptions with digests and mute."}]]},"headers":[],"relativePath":"features/notifications.md","filePath":"features/notifications.md","lastUpdated":1790511576000}'),c={name:"features/notifications.md"};function d(p,e,g,u,k,m){const s=i("Needs");return n(),o("div",null,[e[0]||(e[0]=t("h1",{id:"notifications-alerts",tabindex:"-1"},[r("Notifications & alerts "),t("a",{class:"header-anchor",href:"#notifications-alerts","aria-label":'Permalink to "Notifications & alerts"'},"​")],-1)),h(s,{reporter:""}),e[1]||(e[1]=l(`<p>Piwi pushes run events to a <strong>browser</strong> tab, <strong>email</strong>, <strong>Slack</strong>, <strong>Microsoft Teams</strong> or an <strong>HTTP webhook</strong>, so your team hears about failures, new failure clusters, flakiness spikes and performance regressions without watching the dashboard.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><ol><li>A <strong>channel</strong> is a destination: a browser tab, an email address, a Slack or Teams webhook, or your own URL.</li><li>A <strong>subscription</strong> links a channel to the events you care about, for every project or one, with filters and a delivery mode.</li><li>When an event fires, Piwi matches the active subscriptions and writes each delivery to an outbox, which a scheduled task sends with retries. A browser channel is delivered at once to every open dashboard tab.</li></ol><h2 id="where-it-is" tabindex="-1">Where it is <a class="header-anchor" href="#where-it-is" aria-label="Permalink to &quot;Where it is&quot;">​</a></h2><p><strong>Settings → Notifications</strong> manages channels and subscriptions, and the <strong>bell</strong> on a project page subscribes to that project. The new-channel form shows where to get each destination, flags a URL that belongs to another type (a Slack URL pasted under Teams offers to switch), and can <strong>send a test</strong> before saving: a channel whose test went through is saved as verified. Notifications need no authentication: with it off, the instance is single-tenant and every channel and subscription is <strong>global</strong>. With <code>PIWI_AUTH_ENABLED=true</code> (<a href="/operate/authentication.html">authentication</a>), each user keeps their own, and administrators can add global ones shared by everyone.</p><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><p>Run events fire when a run finishes or fails, cluster events when a failure cluster appears, is fixed or regresses, and others on a flakiness spike, a performance regression, a finished AI diagnosis and an auto-heal pull request. Each event, when it fires and the payload it carries are in <a href="/reference/notification-events.html">Notification events &amp; webhooks</a>. A <a href="./quality-reports.html#report-schedules">report schedule</a> sends its report to the channels it names, with no subscription.</p><h2 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h2><h3 id="browser" tabindex="-1">Browser <a class="header-anchor" href="#browser" aria-label="Permalink to &quot;Browser&quot;">​</a></h3><p>Sends native OS notifications to any open Piwi tab, even in the background, through the <a href="https://developer.mozilla.org/en-US/docs/Web/API/Notifications_API" target="_blank" rel="noreferrer">Notifications API</a>; grant permission when prompted.</p><ul><li><strong>With authentication</strong>: create a channel of type <code>browser</code> in <strong>Settings → Notifications</strong> and subscribe it to events; the stream then delivers exactly the events and projects your subscriptions cover.</li><li><strong>Without authentication</strong>: no channel is needed; the <strong>bell</strong> on each project page stores per-browser preferences (a cookie) for which events raise notifications.</li></ul><p>The diagnosis panel toggles diagnosis completion notifications without deleting the subscription.</p><h3 id="email" tabindex="-1">Email <a class="header-anchor" href="#email" aria-label="Permalink to &quot;Email&quot;">​</a></h3><p>Requires SMTP to be configured (see below). Sends to a destination address.</p><h3 id="slack" tabindex="-1">Slack <a class="header-anchor" href="#slack" aria-label="Permalink to &quot;Slack&quot;">​</a></h3><p>Paste an <a href="https://docs.slack.dev/messaging/sending-messages-using-incoming-webhooks" target="_blank" rel="noreferrer">incoming webhook</a> URL (<code>https://hooks.slack.com/services/…</code>). Without one, the form&#39;s <strong>Create a Slack app for Piwi</strong> link opens Slack with an app already filled in, asking only for the <code>incoming-webhook</code> permission: create it, choose <strong>Install to Workspace</strong> and the channel, then copy the URL from <strong>Incoming Webhooks</strong>. Messages are posted to that channel. A Slack-compatible server (Mattermost, Rocket.Chat) works too.</p><h3 id="microsoft-teams" tabindex="-1">Microsoft Teams <a class="header-anchor" href="#microsoft-teams" aria-label="Permalink to &quot;Microsoft Teams&quot;">​</a></h3><p>In the Teams channel&#39;s <strong>⋯</strong> menu, open <strong>Workflows</strong>, pick the template <em>Send webhook alerts to a channel</em>, choose the team and channel, and paste the URL the workflow shows. A legacy Microsoft 365 connector webhook still works while Microsoft keeps it, and the form flags it. Each event, digest and <a href="./quality-reports.html#report-schedules">quality report</a> arrives as an Adaptive Card.</p><h3 id="webhook" tabindex="-1">Webhook <a class="header-anchor" href="#webhook" aria-label="Permalink to &quot;Webhook&quot;">​</a></h3><p>Piwi <code>POST</code>s a JSON body to your URL, signed with an HMAC-SHA256 <code>X-Piwi-Signature</code> header derived from the channel&#39;s secret, which the form can generate (storing it needs <code>PIWI_SECRET_KEY</code>). Private and loopback addresses are refused. The body, its fields and how to verify the signature are in <a href="/reference/notification-events.html#webhook-body">Notification events &amp; webhooks</a>.</p><h3 id="reaching-the-person-who-fixed-it" tabindex="-1">Reaching the person who fixed it <a class="header-anchor" href="#reaching-the-person-who-fixed-it" aria-label="Permalink to &quot;Reaching the person who fixed it&quot;">​</a></h3><p>When an <a href="/guide/source-control.html">SCM token</a> is configured, <code>cluster.fixed</code> and <code>cluster.regressed</code> resolve the fixing commit&#39;s author through the provider (for a regression, the author of the fix that did not hold). On top of the normal subscription routing, the event is then delivered to that person directly:</p><ul><li><strong>Email</strong>, through the same outbox, when SMTP is configured <strong>and</strong> the commit&#39;s email belongs to a registered Piwi user. The mail goes to that user&#39;s account email, never to the raw commit address, so a fix by an outside contributor never becomes a mail to a stranger.</li><li><strong>A browser notification</strong> for that user, delivered even when they have no matching subscription.</li></ul><p>Without a token, an exposed email or a successful lookup, subscriptions alone apply.</p><h3 id="global-channels-subscriptions" tabindex="-1">Global channels &amp; subscriptions <a class="header-anchor" href="#global-channels-subscriptions" aria-label="Permalink to &quot;Global channels &amp; subscriptions&quot;">​</a></h3><p>Admins can mark a channel <strong>global</strong> so it is available to all users, and mark a subscription <strong>instance-wide</strong> (from the project bell) so it delivers whoever is signed in: the way to route every failure to one team Slack channel. Global subscriptions must target a global channel. With authentication disabled, every channel and subscription is global.</p><h2 id="subscriptions" tabindex="-1">Subscriptions <a class="header-anchor" href="#subscriptions" aria-label="Permalink to &quot;Subscriptions&quot;">​</a></h2><p>A subscription controls <em>what</em> is delivered and <em>how</em>:</p><ul><li><strong>Events</strong>: one or more of the events above.</li><li><strong>Scope</strong>: all projects, or a single project.</li><li><strong>Filters</strong>: by branch, status, <strong>owner</strong> (only when the run broke a test that team owns; see <a href="/guide/concepts.html#tags-ownership">Tags &amp; ownership</a>), or a numeric threshold (such as flakiness above N%).</li><li><strong>Mode</strong>: <code>realtime</code>, sent as events happen, or <code>digest</code>, held until the configured time and sent as <strong>one combined message</strong> per email, Slack or Teams channel.</li><li><strong>Mute</strong>: silence a subscription until a chosen time without deleting it.</li></ul><h2 id="smtp-configuration" tabindex="-1">SMTP configuration <a class="header-anchor" href="#smtp-configuration" aria-label="Permalink to &quot;SMTP configuration&quot;">​</a></h2><p>Email channels and the account flows (verification, password reset, invites) need SMTP. Slack, webhook and browser channels work without it. SMTP is set via environment variables only and shown read-only in <strong>Settings → Notifications</strong>; <code>PIWI_SMTP_HOST</code> and <code>PIWI_SMTP_FROM</code> are enough for a relay that accepts unauthenticated mail:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_SMTP_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">smtp.example.com</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_SMTP_PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">587</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # default 587</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_SMTP_FROM</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">noreply@example.com</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_SMTP_FROM_NAME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Piwi</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Dashboard</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # optional display name</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_SMTP_USER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">apikey</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # only when the server requires authentication</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_SMTP_PASS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">••••••••</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # only when the server requires authentication; never returned by the API</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_SMTP_SECURE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">false</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # true for port 465 (implicit TLS)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_SITE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://piwi.example.com</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # base URL used in email links</span></span></code></pre></div><p>Send a test email from <strong>Settings → Notifications</strong> to confirm delivery.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Digests group email, Slack and Teams only.</strong> Webhook and browser deliveries are always one per event.</li><li><strong>A browser channel needs an open tab.</strong> Nothing reaches a closed browser; the <a href="./desktop.html">desktop app</a> shows OS notifications while its window is in the background.</li><li><strong>Email needs SMTP</strong>, set through environment variables only.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/guide/ci.html">CI &amp; sharding</a>: the alternative, pulling the run URL into your pipeline</li><li><a href="/operate/authentication.html">Authentication</a>: per-user channels and subscriptions</li><li><a href="/reference/configuration.html">Configuration reference</a>: every environment variable</li><li><a href="/reference/notification-events.html">Notification events &amp; webhooks</a>: every event and the webhook body</li><li><a href="./quality-reports.html#report-schedules">Quality reports</a>: scheduled quality reports sent to these channels</li><li><a href="./failure-clusters.html">Failure clusters &amp; the inbox</a>: what triggers the cluster events</li></ul>`,37))])}const w=a(c,[["render",d]]);export{b as __pageData,w as default};
